<script setup lang="ts">
import { ref,onMounted } from 'vue';import { useAuth } from '@/stores/auth';import { useRouter } from 'vue-router'
import {request} from '@/lib/request'
const captcha=ref<{captchaOnOff:boolean;uuid?:string;img?:string}>({captchaOnOff:false}),code=ref('');async function refreshCaptcha(){captcha.value=await request('/api/captchaImage',{public:true,scope:'platform'});code.value=''};onMounted(refreshCaptcha)
const username=ref(''),password=ref(''),loading=ref(false),error=ref(''),auth=useAuth(),router=useRouter()
async function login(){loading.value=true;error.value='';try{await auth.login(username.value,password.value,code.value,captcha.value.uuid);password.value='';await router.replace('/')}catch(e){password.value='';error.value=e instanceof Error?e.message:'登录失败'}finally{loading.value=false;await refreshCaptcha()}}
</script><template><div class="login-shell"><form class="login-card" @submit.prevent="login"><p class="eyebrow">MES BASE</p><h1>登录管理工作台</h1><p class="muted">账号身份与工厂权限独立管理</p><el-alert v-if="error" type="error" :title="error" :closable="false"/><label>账号<el-input v-model="username" autocomplete="username" placeholder="请输入账号" required /></label><label>密码<el-input v-model="password" type="password" autocomplete="current-password" show-password required /></label><label v-if="captcha.captchaOnOff">验证码<div style="display:flex;align-items:center;gap:12px"><el-input v-model="code" placeholder="请输入验证码" autocomplete="off"/><button type="button" @click="refreshCaptcha" style="border:0;padding:0;background:none"><img :src="'data:image/png;base64,'+captcha.img" alt="刷新验证码" width="128" /></button></div></label><el-button type="primary" native-type="submit" :loading="loading" style="width:100%">登录</el-button><p class="small muted">没有默认账号。请联系平台管理员开通。</p></form></div></template>
